import sys

def min_operations_to_one_inversion(n, p):
    if n == 2:
        return 0 if p[0] > p[1] else 1
    min_ops = float('inf')
    for i in range(n):
        for j in range(i + 1, n):
            p[i], p[j] = p[j], p[i]
            inversions = 0
            for k in range(n):
                for l in range(k + 1, n):
                    if p[k] > p[l]:
                        inversions += 1
            if inversions == 1:
                min_ops = min(min_ops, 1)
            p[i], p[j] = p[j], p[i]
    return min_ops if min_ops != float('inf') else -1

input = sys.stdin.read().strip().split()
index = 0
t = int(input[index])
index += 1
results = []
for _ in range(t):
    n = int(input[index])
    index += 1
    p = list(map(int, input[index:index + n]))
    index += n
    results.append(min_operations_to_one_inversion(n, p))
print('\n'.join(map(str, results)))
